import { ApiError, AuthUser, StaffCredentials, authApi } from '../services/authApi';
import { store } from '../services/store';
import { StaffRole } from '../types';

const ROLE_OPTIONS: { role: StaffRole; label: string }[] = [
  { role: 'Recruiter', label: 'Recruiter / HR' },
  { role: 'Proctor', label: 'Live Proctor' },
  { role: 'System Admin', label: 'System Administrator' },
];

const ROLE_BADGE: Record<string, string> = {
  'System Admin': 'bg-purple-500/10 text-purple-400 border-purple-500/20',
  Recruiter: 'bg-blue-500/10 text-blue-400 border-blue-500/20',
  Proctor: 'bg-red-500/10 text-red-400 border-red-500/20',
};

const PORTAL_PATH_FOR_ROLE: Record<string, string> = {
  'System Admin': '/admin',
  Recruiter: '/recruiter',
  Proctor: '/proctor',
};

const esc = (value: string) =>
  String(value ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c] as string));

const errorText = (e: unknown) => (e instanceof ApiError ? e.message : 'Something went wrong. Please try again.');

/**
 * "Staff Management" tab of the System Admin portal.
 * Accounts are only ever created here (no self-registration); the admin also resets passwords here.
 * Keeps its own data (not the global store) so the app-wide re-render doesn't lose a half-filled dialog.
 */
export class StaffManagementPanel {
  private static cache: AuthUser[] | null = null;

  private container: HTMLElement;
  private accounts: AuthUser[] = StaffManagementPanel.cache || [];
  private loading = !StaffManagementPanel.cache;
  private error = '';

  constructor(container: HTMLElement) {
    this.container = container;
  }

  public mount() {
    this.render();
    this.reload().catch(() => {});
  }

  private async reload() {
    try {
      this.accounts = await authApi.listStaff();
      StaffManagementPanel.cache = this.accounts;
      this.error = '';
    } catch (e) {
      this.error = errorText(e);
    } finally {
      this.loading = false;
      if (this.container.isConnected) this.render();
    }
  }

  private render() {
    const me = store.getState().currentUser;

    this.container.innerHTML = `
      <div class="glass-panel p-6 rounded-3xl border border-slate-800 space-y-5">
        <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-3 border-b border-slate-800 pb-4">
          <div>
            <h2 class="text-lg font-bold text-white">Staff Management</h2>
            <p class="text-xs text-slate-400 mt-0.5">
              Only you can create staff accounts and reset passwords. New users get a temporary password and must choose their own at first sign-in.
            </p>
          </div>
          <button id="add-staff-btn" class="px-4 py-2 rounded-xl bg-blue-600 hover:bg-blue-500 text-white font-bold text-xs tracking-wider shadow-md transition-all">
            ＋ Add Staff Member
          </button>
        </div>

        ${this.error ? `<p class="text-xs font-semibold text-red-400">${esc(this.error)}</p>` : ''}

        <div class="overflow-x-auto">
          <table class="w-full text-left text-xs">
            <thead>
              <tr class="border-b border-slate-800 text-slate-400 font-semibold uppercase text-[10px]">
                <th class="py-2.5 px-3">Name</th>
                <th class="py-2.5 px-3">Email</th>
                <th class="py-2.5 px-3">Role / Portal</th>
                <th class="py-2.5 px-3">Status</th>
                <th class="py-2.5 px-3">Created</th>
                <th class="py-2.5 px-3 text-right">Actions</th>
              </tr>
            </thead>
            <tbody class="divide-y divide-slate-800/60 text-slate-300">
              ${this.loading ? `<tr><td colspan="6" class="py-6 px-3 text-center text-slate-500">Loading staff accounts…</td></tr>` : ''}
              ${!this.loading && this.accounts.length === 0 ? `<tr><td colspan="6" class="py-6 px-3 text-center text-slate-500">No staff accounts yet.</td></tr>` : ''}
              ${this.accounts.map(u => this.rowHtml(u, me?.id === u.id)).join('')}
            </tbody>
          </table>
        </div>
      </div>
      <div id="staff-modal-host"></div>
    `;

    this.attachEvents();
  }

  private rowHtml(u: AuthUser, isSelf: boolean): string {
    const active = u.isActive !== false;
    return `
      <tr class="hover:bg-slate-800/40 ${active ? '' : 'opacity-60'}">
        <td class="py-2.5 px-3 font-bold text-white">${esc(u.name)}${isSelf ? ' <span class="ml-1 text-[10px] text-slate-500 font-normal">(you)</span>' : ''}</td>
        <td class="py-2.5 px-3 font-mono text-blue-400">${esc(u.email)}</td>
        <td class="py-2.5 px-3">
          ${isSelf
            ? `<span class="px-2 py-0.5 rounded-full text-[10px] font-bold border ${ROLE_BADGE[u.role] || ''}">${esc(u.role)}</span>`
            : `<select data-role-for="${u.id}" class="glass-input px-2 py-1 rounded-lg border border-slate-700 bg-slate-950 text-white text-[11px] font-semibold">
                 ${ROLE_OPTIONS.map(o => `<option value="${o.role}" ${o.role === u.role ? 'selected' : ''}>${o.label}</option>`).join('')}
               </select>`}
        </td>
        <td class="py-2.5 px-3">
          <div class="flex flex-col items-start gap-1">
            <span class="whitespace-nowrap px-2 py-0.5 rounded-full text-[10px] font-bold border ${active ? 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20' : 'bg-slate-500/10 text-slate-400 border-slate-500/20'}">${active ? 'Active' : 'Disabled'}</span>
            ${u.mustChangePassword ? '<span class="whitespace-nowrap px-2 py-0.5 rounded-full text-[10px] font-bold border bg-amber-500/10 text-amber-400 border-amber-500/20">Awaiting new password</span>' : ''}
          </div>
        </td>
        <td class="py-2.5 px-3 text-slate-400 font-mono whitespace-nowrap">${esc((u.createdAt || '').split('T')[0])}</td>
        <td class="py-2.5 px-3 text-right whitespace-nowrap">
          ${isSelf ? '<span class="text-[11px] text-slate-500">—</span>' : `
            <button data-reset="${u.id}" class="px-2.5 py-1 rounded-lg bg-slate-800 hover:bg-slate-700 border border-slate-700 text-amber-300 font-bold text-[11px]">Reset password</button>
            <button data-toggle="${u.id}" class="ml-1 px-2.5 py-1 rounded-lg bg-slate-800 hover:bg-slate-700 border border-slate-700 ${active ? 'text-red-300' : 'text-emerald-300'} font-bold text-[11px]">${active ? 'Deactivate' : 'Activate'}</button>
          `}
        </td>
      </tr>
    `;
  }

  private find(id: string | null): AuthUser | undefined {
    return this.accounts.find(u => u.id === id);
  }

  /** Run a mutation, then refresh the list; failures are shown in the panel. */
  private async mutate<T>(action: () => Promise<T>): Promise<T | undefined> {
    this.error = '';
    try {
      const result = await action();
      await this.reload();
      return result;
    } catch (e) {
      this.error = errorText(e);
      this.render();
      return undefined;
    }
  }

  private attachEvents() {
    const q = (sel: string) => this.container.querySelector(sel);

    q('#add-staff-btn')?.addEventListener('click', () => this.openCreateDialog());

    this.container.querySelectorAll('[data-role-for]').forEach(sel =>
      sel.addEventListener('change', e => {
        const el = e.currentTarget as HTMLSelectElement;
        const user = this.find(el.getAttribute('data-role-for'));
        if (!user) return;
        const role = el.value as StaffRole;
        if (!confirm(`Change ${user.name} from ${user.role} to ${role}? They will be signed out and must use the ${role} portal.`)) {
          el.value = user.role;
          return;
        }
        this.mutate(async () => {
          await authApi.updateStaff(user.id, { role });
        }).catch(() => {});
      }));

    this.container.querySelectorAll('[data-toggle]').forEach(btn =>
      btn.addEventListener('click', e => {
        const user = this.find((e.currentTarget as HTMLElement).getAttribute('data-toggle'));
        if (!user) return;
        const next = user.isActive === false;
        if (!next && !confirm(`Deactivate ${user.name}? They will be signed out immediately.`)) return;
        this.mutate(async () => {
          await authApi.updateStaff(user.id, { isActive: next });
        }).catch(() => {});
      }));

    this.container.querySelectorAll('[data-reset]').forEach(btn =>
      btn.addEventListener('click', e => {
        const user = this.find((e.currentTarget as HTMLElement).getAttribute('data-reset'));
        if (!user) return;
        if (!confirm(`Reset the password for ${user.name}? A new temporary password is generated and they are signed out everywhere.`)) return;
        // The dialog opens after the list re-render, otherwise the re-render would wipe it.
        this.mutate(() => authApi.resetStaffPassword(user.id))
          .then(result => { if (result) this.openCredentialsDialog(result, true); })
          .catch(() => {});
      }));
  }

  // ------------------------------------------------------------------ dialogs
  private modalHost(): HTMLElement | null {
    return this.container.querySelector('#staff-modal-host');
  }

  private openCreateDialog(error = '', draft = { name: '', email: '', role: 'Recruiter' as StaffRole }) {
    const host = this.modalHost();
    if (!host) return;

    host.innerHTML = `
      <div class="fixed inset-0 z-[60] bg-slate-950/80 backdrop-blur-md overflow-y-auto"><div class="min-h-full flex items-center justify-center p-4">
        <div class="glass-panel w-full max-w-md rounded-3xl border border-slate-800 p-7 space-y-5 shadow-2xl">
          <div class="flex items-center justify-between border-b border-slate-800 pb-3">
            <h3 class="text-lg font-extrabold text-white">Add staff member</h3>
            <button id="cs-close" class="text-slate-400 hover:text-white font-bold">✕</button>
          </div>
          <p id="cs-error" class="text-xs font-semibold text-red-400 ${error ? '' : 'hidden'}">${esc(error)}</p>
          <div class="space-y-4 text-xs">
            <div>
              <label class="block font-semibold text-slate-300 mb-1" for="cs-name">Full name</label>
              <input id="cs-name" type="text" value="${esc(draft.name)}" class="glass-input w-full px-3.5 py-2.5 rounded-xl border border-slate-700 bg-slate-950 text-white" placeholder="Jane Doe" />
            </div>
            <div>
              <label class="block font-semibold text-slate-300 mb-1" for="cs-email">Work email (also where their 2FA codes go)</label>
              <input id="cs-email" type="text" value="${esc(draft.email)}" class="glass-input w-full px-3.5 py-2.5 rounded-xl border border-slate-700 bg-slate-950 text-white font-mono" placeholder="jane@company.com" />
            </div>
            <div>
              <label class="block font-semibold text-slate-300 mb-1" for="cs-role">Role</label>
              <select id="cs-role" class="glass-input w-full px-3.5 py-2.5 rounded-xl border border-slate-700 bg-slate-950 text-white font-semibold">
                ${ROLE_OPTIONS.map(o => `<option value="${o.role}" ${o.role === draft.role ? 'selected' : ''}>${o.label}</option>`).join('')}
              </select>
            </div>
            <p class="text-[11px] text-slate-500">A temporary password is generated and emailed. They must replace it when they first sign in.</p>
            <button id="cs-submit" class="w-full py-3 rounded-xl bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-500 hover:to-indigo-500 text-white font-bold text-xs tracking-wider shadow-lg shadow-blue-600/30 disabled:opacity-60">
              CREATE ACCOUNT ➔
            </button>
          </div>
        </div>
      </div></div>
    `;

    const close = () => { host.innerHTML = ''; };
    host.querySelector('#cs-close')?.addEventListener('click', close);

    const submit = host.querySelector('#cs-submit') as HTMLButtonElement;
    const val = (sel: string) => ((host.querySelector(sel) as HTMLInputElement | HTMLSelectElement).value || '').trim();
    const run = () => {
      const data = { name: val('#cs-name'), email: val('#cs-email'), role: val('#cs-role') as StaffRole };
      if (!data.name || !data.email) {
        const el = host.querySelector('#cs-error');
        if (el) { el.textContent = 'Enter a name and an email.'; el.classList.remove('hidden'); }
        return;
      }
      submit.disabled = true;
      authApi.createStaff(data)
        .then(async result => {
          close();
          await this.reload();
          this.openCredentialsDialog(result, false);
        })
        .catch(e => this.openCreateDialog(errorText(e), data));
    };
    submit.addEventListener('click', run);
    host.querySelectorAll('input').forEach(i => i.addEventListener('keydown', e => {
      if ((e as KeyboardEvent).key === 'Enter') run();
    }));
    (host.querySelector('#cs-name') as HTMLInputElement)?.focus();
  }

  /** Shows the temporary password exactly once. */
  private openCredentialsDialog(result: StaffCredentials, isReset: boolean) {
    const host = this.modalHost();
    if (!host) return;

    host.innerHTML = `
      <div class="fixed inset-0 z-[60] bg-slate-950/80 backdrop-blur-md overflow-y-auto"><div class="min-h-full flex items-center justify-center p-4">
        <div class="glass-panel w-full max-w-md rounded-3xl border border-slate-800 p-7 space-y-5 shadow-2xl">
          <div class="flex items-center justify-between border-b border-slate-800 pb-3">
            <h3 class="text-lg font-extrabold text-white">${isReset ? 'Password reset' : 'Account created'}</h3>
            <button id="cr-close" class="text-slate-400 hover:text-white font-bold">✕</button>
          </div>
          <div class="space-y-3 text-xs">
            <p class="text-slate-300"><b class="text-white">${esc(result.user.name)}</b> (${esc(result.user.role)}) —
              <span class="font-mono text-blue-400">${esc(result.user.email)}</span></p>
            <div>
              <label class="block font-semibold text-slate-300 mb-1">Temporary password</label>
              <div class="flex gap-2">
                <input id="cr-pass" readonly value="${esc(result.temporaryPassword)}" class="glass-input flex-1 px-3.5 py-2.5 rounded-xl border border-slate-700 bg-slate-950 text-emerald-400 font-mono text-sm tracking-wider" />
                <button id="cr-copy" class="px-3 rounded-xl bg-slate-800 hover:bg-slate-700 border border-slate-700 text-slate-200 font-bold">Copy</button>
              </div>
            </div>
            <p class="p-3 rounded-xl bg-amber-500/10 border border-amber-500/30 text-amber-300 text-[11px]">
              This is the only time the password is shown. ${result.emailed ? 'It has also been emailed to the user.' : ''}
              They must choose a new password when they sign in at <b>${esc(PORTAL_PATH_FOR_ROLE[result.user.role] || '/')}</b>.
            </p>
            <button id="cr-done" class="w-full py-3 rounded-xl bg-blue-600 hover:bg-blue-500 text-white font-bold text-xs tracking-wider">DONE</button>
          </div>
        </div>
      </div></div>
    `;

    const close = () => { host.innerHTML = ''; };
    host.querySelector('#cr-close')?.addEventListener('click', close);
    host.querySelector('#cr-done')?.addEventListener('click', close);
    host.querySelector('#cr-copy')?.addEventListener('click', async e => {
      const btn = e.currentTarget as HTMLButtonElement;
      try {
        await navigator.clipboard.writeText(result.temporaryPassword);
        btn.textContent = 'Copied ✓';
      } catch {
        (host.querySelector('#cr-pass') as HTMLInputElement)?.select();
        btn.textContent = 'Press Ctrl+C';
      }
    });
  }
}
